__global__ void conv1d_valid(const float* input, const float* weight, const float* bias, float* output, int n) {
  int t = blockIdx.x * blockDim.x + threadIdx.x;
  if (t >= n) {
    return;
  }
  int inputLength = n + 2;
  float sum = bias[0];
  for (int k = 0; k < 3; k++) {
    if (t + k < inputLength) {
      sum += input[t + k] * weight[k];
    }
  }
  output[t] = sum;
}
